package com.ruoyi.business.ai.capability.project;
import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import com.ruoyi.business.ai.capability.*;import com.ruoyi.business.service.IBusinessProjectService;import static com.ruoyi.business.ai.capability.AiCapabilityInputs.*;
@Component public class RemoveProjectMemberCapability implements AiConfirmableCapability{private final IBusinessProjectService service;@Autowired public RemoveProjectMemberCapability(IBusinessProjectService s){service=s;}public String code(){return "project.member.remove";}public String description(){return "将非主负责人从项目成员中移除。先读取项目详情确认人员ID；确认后执行。";}public String requiredPermission(){return "business:project:member";}public Map<String,Object> inputSchema(){Map<String,Object>s=AiSchemas.object();AiSchemas.property(s,"projectId","number","项目ID");AiSchemas.property(s,"staffUserId","number","要移除的人员ID");AiSchemas.property(s,"staffName","string","人员姓名，仅用于确认展示");return AiSchemas.required(s,"projectId","staffUserId");}public String confirmationSummary(AiCapabilityInvocation i,Map<String,Object>in){return "从项目中移除“"+(text(in.get("staffName")).isEmpty()?"人员ID "+number(in.get("staffUserId")):text(in.get("staffName")))+"”";}public Map<String,Object> executeConfirmed(AiCapabilityInvocation i,Map<String,Object>in){service.removeMember(number(in.get("projectId")),number(in.get("staffUserId")),i.getActor().getUserId(),i.getActor().getUserName(),true);Map<String,Object>r=new LinkedHashMap<String,Object>();r.put("projectId",number(in.get("projectId")));r.put("staffUserId",number(in.get("staffUserId")));r.put("status","REMOVED");return r;}}
